import { readFileSync, writeFileSync } from 'node:fs';
const root = new URL('../', import.meta.url);
const read = (path) => readFileSync(new URL(`skills/h3-ref2va-prompt-writing/${path}`, root), 'utf8');
writeFileSync(new URL('src/lib/workshop/h3Ref2vaSkillContent.ts', root),
  '// Generated by scripts/sync-h3-ref2va-skill.mjs; edit the independent skill source.\n' +
  `export const REF2VA_SKILL = ${JSON.stringify(read('SKILL.md'))};\n` +
  `export const REF2VA_GUIDE = ${JSON.stringify(read('references/ref-en.txt'))};\n`);
